async def list_dialogs(
    subpath:str='', # Path under data root (absolute with `/`, else relative to current dialog's folder)
    depth:int=1 # Directory depth
) -> dict:
    "List dialogs and folders under `subpath`. Folders have `/` suffix."
    return await _rg('GET', '/api/dialogs', **_target(subpath), depth=depth)

# %% ../nbs/00_core.ipynb #92879524
def data_root():
    "The gateway root recorded at startup, or derived from the current notebook's folder"
    if r := dh_settings.get('root'): return Path(r)
    if not (nm := find_dname(required=False)): raise RuntimeError('data_root requires a bound gateway kernel')
    root = Path.cwd()
    for _ in Path(nm).parent.parts: root = root.parent
    return root

# %% ../nbs/00_core.ipynb #c4582c78
def _target(dname=''):
    return dict(kid=dh_settings.get('kid'), path=dname or None)

# %% ../nbs/00_core.ipynb #57ee78dd
def _lnhashs_content(s, start_line=1, end_line=None):
    "Render `s` as `lineno|hash|` prefixed lines, sliced by optional 1-based line range (`end_line` None or -1 for EOF)"
    lines = [lnhash(i,l)+l for i,l in enumerate(s.splitlines(), 1)]
    return '\n'.join(lines[start_line-1:len(lines) if end_line in (None,-1) else end_line])

# %% ../nbs/00_core.ipynb #9672dd87
def _mid(id):
    "Message `id` without the `_` prefix of its DOM form, as in `_f5fd1d54`"
    return id.removeprefix('_') if id else id

def _ids(ids):
    "Message ids from a comma-separated string or a list, with blank entries dropped"
    if isinstance(ids, str): ids = ids.split(',')
    return [o.strip() for o in listify(ids) if o.strip()]

async def _caller():
    "Id of the cell this code runs for: the running cell, or a tool call's prompt cell (None outside any cell)"
    if not (kid := dh_settings.get('kid')): return None
    return (await _rg('GET', f'/api/kernels/{kid}/caller'))['cell']

# %% ../nbs/00_core.ipynb #558c6aa7
async def read_msg(
    n:int=-1,      # Message index (if relative, +ve is downwards)
    relative:bool=True,  # Is `n` relative to current message (True) or absolute (False)?
    id:str=None,  # Message id to find (defaults to current message)
    start_line:int=1, # Starting line to view
    end_line:int=None, # End line (defaults to last line if None; -1 for EOF)
    nums:bool=False, # Whether to show line numbers
    lnhashs:bool=False, # Show exhash `lineno|hash|` addresses instead of line numbers?
    dname:str='' # Dialog to get info for; defaults to current dialog
    ) -> dict|None:
    """Get the message indexed in the current dialog, or None when there's no such message.
    NB: Messages in the current dialog above the current message are *already* visible; use this only when you need line numbers for editing operations, or for messages not in the current dialog or below the current message.
    - To get the exact message use `n=0` and `relative=True` together with `id`.
    - To get a relative message use `n` (relative position index).
    - To get the nth message use `n` with `relative=False`, e.g `n=0` first message, `n=-1` last message."""
    if start_line<1: raise ValueError('start_line must be at least 1')
    found = await _rg('GET', '/api/messages', **_target(dname), id=id, n=n, relative=relative)
    if not found: return None
    res = AttrDict(found[0])
    if lnhashs: res['content'] = _lnhashs_content(res['content'], start_line, end_line)
    elif start_line!=1 or end_line is not None:
        lines = res['content'].splitlines()
        e = len(lines) if end_line in (None,-1) else end_line
        lines = lines[start_line-1:e]
        if nums: lines = [f'{i+start_line:6d} │ {l}' for i,l in enumerate(lines)]
        res['content'] = '\n'.join(lines)
    elif nums: res['content'] = '\n'.join(f'{i:6d} │ {l}' for i,l in enumerate(res['content'].splitlines(), 1))
    return res

# %% ../nbs/00_core.ipynb #c7d57efa
def _trunc_middle(s, limit=500, msg='\n…TRUNCATED…\n'):
    "Middle-out truncation, keeping both ends of `s`"
    if len(s) <= limit: return s
    i = limit//2
    return s[:i] + msg + s[len(s)-(limit-i):]

def _msgs2xml(ds, ids=True):
    "Message dicts as concise XML, in the shared `item2xml` grammar"
    its = [item2xml({'note':'markdown'}.get(d['msg_type'], d['msg_type']), d.get('content',''), d.get('output') or '',
        id=d.get('id') if ids else None, meta=d.get('meta')) for d in ds]
    return to_xml(Msgs(*its), do_escape=False)

# %% ../nbs/00_core.ipynb #6a4aa03b
async def find_msgs(
    re_pattern:str='', # Optional regex to search for (re.DOTALL+re.MULTILINE is used)
    msg_type:str=None, # optional limit by message type ('code', 'note', or 'prompt')
    before:int=0,  # Include additional n msgs before matches
    after:int=0,   # Include additional n msgs after matches
    context:int=None, # Include additional n msgs around matches (default 1, or 0 when `headers_only`)
    use_case:bool=False, # Use case-sensitive matching?
    use_regex:bool=True, # Use regex matching?
    only_err:bool=None, # Only messages with errors if True, only those without if False, all if None
    only_exp:bool=None, # Only exported messages if True, only unexported if False, all if None
    only_chg:bool=False, # Only messages whose input differs from Git HEAD
    ids:str='', # Optionally filter by comma-separated list of message ids
    limit:int=None, # Optionally limit number of returned items
    include_output:bool=True, # Include output in returned dict?
    include_meta:bool=True, # Include all additional message metadata
    as_xml:bool=False, # Use concise unescaped XML output format
    nums:bool=False, # Show line numbers?
    trunc_out:bool=False, # Middle-out truncate code output to 100 characters?
    trunc_in:bool=False, # Middle-out truncate cell content to 80 characters?
    headers_only:bool=False, # Only return note messages that are headers (first line only); cannot be used together with `header_section`
    header_section:str=None, # Find section starting with this header; returns it plus all children
    include_skipped:bool=False, # Include messages hidden from AI (skipped)?
    dname:str='' # Dialog to get info for; defaults to current dialog
)->list[dict]: # Messages in requested dialog that contain the given information
    """Often it is more efficient to call `view_dlg` (not `find_msgs`) to see the whole dialog, so you can use it all from then on.
    Message ids are identical to those in LLM chat history, so do NOT call this to view a specific message if it's in the chat history--instead use `view_msg`.
    Do NOT use find_msgs to view message content in the current dialog above the current prompt -- these are *already* provided in LLM context, so just read the content there directly. (NB: LLM context only includes messages *above* the current prompt, whereas `find_msgs` can access *all* messages.)
    To refer to a found message from code, use its `id` field."""
    found = await _rg('GET', '/api/messages', **_target(dname), re_pattern=re_pattern, msg_type=msg_type,
        before=before, after=after, context=context, use_case=use_case, use_regex=use_regex, only_err=only_err, only_exp=only_exp,
        only_chg=only_chg, ids=','.join(_ids(ids)) if ids else None, limit=limit, headers_only=headers_only,
        header_section=header_section, include_skipped=include_skipped, raw_prompt_reply=as_xml)
    res = []
    for o in found:
        flds = {'id','content','msg_type','exported'}
        if include_output or o['msg_type']=='prompt': flds.add('output')
        if include_meta: flds |= {'meta','skipped','pinned','bookmark','i_collapsed','o_collapsed','heading_collapsed'}
        o = AttrDict({k:v for k,v in o.items() if k in flds})
        if nums: o['content'] = '\n'.join(f'{i+1:6d} │ {l}' for i,l in enumerate(o['content'].splitlines()))
        if trunc_in: o['content'] = _trunc_middle(o['content'], 160, msg='\n…\n')
        if trunc_out and isinstance(o.get('output'), str) and o['msg_type']!='prompt': o['output'] = _trunc_middle(o['output'], 100, msg='\n…\n')
        if headers_only: o['content'] = o['content'].split('\n', 1)[0] + ('\n<TRUNCATED>' if '\n' in o['content'] else '')
        res.append(o)
    return _msgs2xml(res) if as_xml else res

# %% ../nbs/00_core.ipynb #9ff2a38e
async def view_dlg(
    dname:str='', # Dialog to get info for; defaults to current dialog
    msg_type:str=None, # optional limit by message type ('code', 'note', or 'prompt')
    nums:bool=False, # Whether to show line numbers
    include_output:bool=False, # Include output in returned dict?
    trunc_out:bool=True, # Middle-out truncate code output to 100 characters (only applies if `include_output`)?
    trunc_in:bool=False, # Middle-out truncate cell content to 80 characters?
    include_skipped:bool=False, # Include messages hidden from AI (skipped)?
) -> str:
    "Concise XML view of all messages (optionally filtered by type), not including metadata. Often it is more efficient to call this to see the whole dialog at once (including line numbers if needed), instead of running `find_msgs` or `view_msg` multiple times."
    return await find_msgs(msg_type=msg_type, dname=dname, as_xml=True, nums=nums,
        include_meta=False, include_output=include_output, trunc_out=trunc_out, trunc_in=trunc_in, include_skipped=include_skipped)

