async def copy_msgs(
    ids:str, # Comma-separated ids of message(s) to copy
    cut:bool=False, # Cut message(s)? (If not, copies)
    dname:str='' # Dialog to copy messages from; defaults to current dialog
) -> list:
    "Copy messages to the gateway's clipboard, replacing its contents, and delete them if `cut`"
    ids = _ids(ids)
    await _rg('POST', '/api/messages', **_target(dname), json=dict(op='copy', ids=ids, cut=cut))
    return ids

